def _link_budget(budget):
    """A link's displayed budget in a report: up to the next 5, none below 5."""
    if budget < 5:
        return None
    return math.ceil(budget / 5) * 5


def _task_budget(budgets):
    """A task's total as a report prints it: the links rounded up to 5, plus
    the ones below 5 pooled and rounded up to 10. Copied here so the
    migration keeps its meaning if the report's rules change later.
    """
    shown = sum(_link_budget(b) or 0 for b in budgets)
    small = sum(b for b in budgets if _link_budget(b) is None)
    return shown + (math.ceil(small / 10) * 10 if small > 0 else 0)


def record_requested_budgets(apps, schema_editor):
    """Record for every existing report what it requested for each task."""
    ReportLine = apps.get_model("timetracking", "ReportLine")
    ReportTask = apps.get_model("timetracking", "ReportTask")
    budgets = {}
    for line in ReportLine.objects.filter(link__task__isnull=False).select_related(
        "link"
    ):
        budgets.setdefault((line.report_id, line.link.task_id), []).append(line.budget)
    for (report_id, task_id), amounts in budgets.items():
        ReportTask.objects.update_or_create(
            report_id=report_id,
            task_id=task_id,
            defaults={"budget": _task_budget(amounts)},
        )


